"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[3151],{12(e){e.exports=JSON.parse('{"tag":{"label":"Graphs","permalink":"/concepts/tags/graphs","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"state-space-search-and-optimization/backtracking","title":"Backtracking","description":"Some problems resist every technique seen so far. There is no greedy criterion that guarantees the optimum, the problem does not split into independent halves, and there is no small table of subproblems to fill. Very often the only way to be sure of the answer is to examine the candidate solutions one by one. Backtracking is the paradigm that organizes that examination so that it is systematic (no candidate is forgotten) and as cheap as possible (whole families of candidates are discarded at once).","permalink":"/concepts/state-space-search-and-optimization/backtracking"},{"id":"foundations-of-algorithms/data-structures","title":"Data Structures","description":"In the previous lessons we saw that the efficiency of a solution depends on the strategy we choose. It also depends, just as much, on how the data is organized in memory. The maximum pairwise product already gave us a hint: the same algorithm used several times more memory with a List than with an int[].","permalink":"/concepts/foundations-of-algorithms/data-structures"}],"unlisted":false}}')}}]);